package greeter

import "strings"

// Slug 把名字转成用于页面锚点的 URL 友好 slug：
// 转小写、连续空白折成单个连字符、首尾不留连字符。
func Slug(name string) string {
	return strings.ToLower(strings.Join(strings.Fields(name), "-"))
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{"single word", "Ada", "ada"},
		{"two words", "Ada Lovelace", "ada-lovelace"},
		{"already lowercase", "ada lovelace", "ada-lovelace"},
		{"mixed case", "aDA lOVELACE", "ada-lovelace"},
		{"leading and trailing blanks", "  Ada Lovelace  ", "ada-lovelace"},
		{"blank run folded to one hyphen", "Ada \t\n Lovelace", "ada-lovelace"},
		{"tab and newline separated", "Ada\tLovelace\n", "ada-lovelace"},
		{"existing hyphen kept", "Ada-Lovelace", "ada-lovelace"},
		{"empty", "", ""},
		{"only blanks", " \t\n ", ""},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Slug(tt.in); got != tt.want {
				t.Fatalf("Slug(%q) = %q, want %q", tt.in, got, tt.want)
			}
		})
	}
}
